#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<int> res(n);
        int left = 0, right = (n + 1) / 2, idx = 0;

        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0)
                res[i] = nums[left++];
            else
                res[i] = nums[right++];
        }
        return res;
    }
};
